sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// Get the field values from the Workspace Maintenance record
	var mainStatus = current.getValue('ticket_status'); 
	var mainWorkspaceStatus = current.getValue('workspace_status'); 

	// Get the Workspace reference from the maintenance record
	var workspaceID = current.getValue('workspace'); 

	// Making sure a workspace is selected
	if (!workspaceID) {
		gs.info('Workspace Maintenace: No workspace found.');
		return;
	}

	// Find the corresponding Worspace Options record		
	var workspaceGR = new GlideRecord('x_1209398_wrm_workspace_options');

	// Update Workspace Options status	
	if (mainStatus == 'open' && mainWorkspaceStatus == 'in_maintenance') {

		workspaceGR.setValue('status','unavailable');
		workspaceGR.update();

	} 
	else if(mainStatus == 'closed' && mainWorkspaceStatus == 'available'){

		workspaceGR.setValue('status','available');
		workspaceGR.update();
	}
	else if(mainStatus == 'closed' && mainWorkspaceStatus == 'decommissioned'){

		workspaceGR.setValue('status', 'decommissioned');
		workspaceGR.update();
	}		

})(current, previous);
